package com.flashsale;
import com.flashsale.service.InventoryService; import java.util.*; import java.util.concurrent.*; import org.junit.jupiter.api.*; import org.springframework.data.redis.connection.*; import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory; import org.springframework.data.redis.core.StringRedisTemplate; import org.testcontainers.containers.GenericContainer; import org.testcontainers.junit.jupiter.*; import org.testcontainers.utility.DockerImageName;
@Testcontainers(disabledWithoutDocker=true) class InventoryConcurrencyTest { @Container static final GenericContainer<?> REDIS=new GenericContainer<>(DockerImageName.parse("redis:7-alpine")).withExposedPorts(6379); static LettuceConnectionFactory connection; static InventoryService inventory; @BeforeAll static void setup(){connection=new LettuceConnectionFactory(new RedisStandaloneConfiguration(REDIS.getHost(),REDIS.getMappedPort(6379)));connection.afterPropertiesSet();inventory=new InventoryService(new StringRedisTemplate(connection));}@AfterAll static void stop(){connection.destroy();}@Test void neverOversellsUnderContention() throws Exception {inventory.seed("concert-ticket",50);ExecutorService pool=Executors.newFixedThreadPool(32);List<Future<Long>> results=new ArrayList<>();for(int i=0;i<250;i++){final int index=i;results.add(pool.submit(()->inventory.reserve("concert-ticket","request-"+index)));}long accepted=0;for(Future<Long> result:results)if(result.get()==1)accepted++;pool.shutdown();Assertions.assertEquals(50,accepted);Assertions.assertEquals(0,inventory.available("concert-ticket"));}@Test void duplicateDoesNotConsumeAnotherUnit(){inventory.seed("limited-sneaker",2);Assertions.assertEquals(1,inventory.reserve("limited-sneaker","same-click"));Assertions.assertEquals(-1,inventory.reserve("limited-sneaker","same-click"));Assertions.assertEquals(1,inventory.available("limited-sneaker"));} }
